//! A pre-ledger lexical index adopts the shared migration ledger in place.

use orbit_common::storage::sqlite::ledger;
use orbit_search::{LexicalIndex, bm25_top_k};
use rusqlite::{Connection, OpenFlags};

// Generated by the lexical schema code at 2e126bdc5227, with a task chunk and
// its sidecar-coverage row inserted before the database was closed.
const PRE_LEDGER_INDEX: &[u8] = include_bytes!("../fixtures/semantic-pre-ledger.db");

#[test]
fn legacy_semantic_database_adopts_ledger_without_losing_indexed_data()
-> Result<(), Box<dyn std::error::Error>> {
    let root = tempfile::tempdir()?;
    let path = root.path().join("semantic.db");
    std::fs::write(&path, PRE_LEDGER_INDEX)?;

    let index = LexicalIndex::open(&path)?;
    let store = index.store()?;
    let hits = bm25_top_k(store, "cobalt observatory", Some("task"), None, 10)?;
    assert_eq!(hits.len(), 1);
    assert_eq!(hits[0].source_id, "legacy-task");
    assert!(
        store
            .substring_task_ids("balt mig")?
            .contains("legacy-task")
    );
    assert!(store.sidecar_indexed_task_ids()?.contains("legacy-task"));
    drop(index);

    let connection = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_ONLY)?;
    let applied = ledger::applied_migrations(&connection)?;
    assert_eq!(applied.len(), 1);
    assert_eq!(
        (applied[0].version, applied[0].name.as_str()),
        (1, "lexical_index_baseline")
    );
    Ok(())
}
